contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 guessHash) public payable {
        require(address(this).balance >= 1 ether);

        c.lockInGuess{value: 1 ether}(guessHash);

        // We cannot easily know the exact blockhash in advance, but we can mine a few blocks
        // by making dummy calls to c so that block.number > guesses[msg.sender].block.
        // However, we cannot call any state-changing function repeatedly without side effects.
        // Instead, we just call settle directly; if the guess is correct it will transfer 2 ether.
        // Since we don't know the blockhash, we just call settle and observe the outcome.
        // But the rule we want is: if the guess was correct, balance increases by 2 ether and block resets.
        // We cannot assert on the guess because we don't have a getter for the mapping.
        // So we assert that calling settle either reverts or transfers exactly 2 ether.
        // But that's trivial. Let's instead assert that if settle does not revert, the contract balance decreases by 2 ether.

        uint256 beforeBalance = address(c).balance;

        bool reverted;
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;

        // The general rule: after a successful lockInGuess, if settle does not revert,
        // it must transfer exactly 2 ether to the caller, and the contract balance must decrease by exactly 2 ether.
        // If settle reverts, the contract balance must remain unchanged.
        assert((!reverted) ? (afterBalance == beforeBalance - 2 ether) : (afterBalance == beforeBalance));
    }

    receive() external payable {}
}

