contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 guessSeed, uint256 lockAmount, uint256 settleWait) public payable {
        require(lockAmount == 1 ether);
        require(address(this).balance >= lockAmount);

        bytes32 guessHash = bytes32(guessSeed);

        uint256 testBalanceBeforeLock = address(this).balance;
        uint256 contractBalanceBeforeLock = address(c).balance;

        c.lockInGuess{value: lockAmount}(guessHash);

        uint256 testBalanceAfterLock = address(this).balance;
        uint256 contractBalanceAfterLock = address(c).balance;

        require(testBalanceAfterLock == testBalanceBeforeLock - lockAmount);
        require(contractBalanceAfterLock == contractBalanceBeforeLock + lockAmount);

        uint256 blocksToAdvance = (settleWait % 256) + 1;
        for (uint256 i = 0; i < blocksToAdvance; i++) {
            // advance block.number by doing a trivial external call
            (bool ok, ) = address(c).call("");
            ok;
        }

        if (block.number <= c.guesses(address(this)).block) {
            return;
        }

        uint256 testBalanceBeforeSettle = address(this).balance;
        uint256 contractBalanceBeforeSettle = address(c).balance;

        c.settle();

        uint256 testBalanceAfterSettle = address(this).balance;
        uint256 contractBalanceAfterSettle = address(c).balance;

        bytes32 answer = blockhash(c.guesses(address(this)).block);
        bool won = (answer != 0 && c.guesses(address(this)).guess == answer);

        if (won) {
            assert(
                testBalanceAfterSettle == testBalanceBeforeSettle + 2 ether &&
                contractBalanceAfterSettle == contractBalanceBeforeSettle - 2 ether
            );
        } else {
            assert(
                testBalanceAfterSettle == testBalanceBeforeSettle &&
                contractBalanceAfterSettle == contractBalanceBeforeSettle
            );
        }
    }

    receive() external payable {}
}

